function patchPreview(patch:string,files:string[]){
  let file=-1,binary=false;
  return patch.split('\n').map(line=>{
    if(line.startsWith('diff --git ')){file++;binary=false;return `<div class="ai-diff-file">${icon('file-code-2')}<span>${e(files[file]??'Changed file')}</span></div>`}
    if(line.startsWith('GIT binary patch')||line.startsWith('Binary files ')){binary=true;return '<div class="ai-diff-meta">Binary contents are not shown.</div>'}
    if(binary||/^index |^--- |^\+\+\+ |^@@ /.test(line))return '';
    if(line.startsWith('new file mode'))return '<div class="ai-diff-meta">New file</div>';
    if(line.startsWith('deleted file mode'))return '<div class="ai-diff-meta">Deleted file</div>';
    return `<div class="ai-diff-line ${line.startsWith('+')?'add':line.startsWith('-')?'remove':''}"><code>${e(line||' ')}</code></div>`;
  }).join('');
}
const status=(s:string)=>({pending_review:'Waiting for you',ready:'Prepared',blocked:'Cannot run',needs_review:'Needs another review',partially_completed:'Partially completed',outcome_unknown:'Result unconfirmed',not_approved:'Waiting',succeeded:'Completed',running:'In progress',approved:'Approved',cancelled:'Stopped',failed:'Failed'}[s]??s.replaceAll('_',' '));
export function commandText(argv:string[],program='git'){return [program,...argv].map(a=>/^[A-Za-z0-9_./:=@,+-]+$/.test(a)?a:`'${a.replaceAll("'","'\\''")}'`).join(' ')}
