    if(next.focusPlanId&&next.focusPlanId!==lastPromptId&&hooks.canPrompt?.()!==false){lastPromptId=next.focusPlanId;open=true;settings=false;selected=next.focusPlanId;diffReview.reset();activeStep=0;activity=false;ack=false;acknowledgedRisks.clear();denyWithReason=false;denialReason='';inboxFilter='waiting';reload=true;}
